export function calculate(rows){let low=0,high=0,priced=0;const errors=[];rows.forEach((r,i)=>{const values=[r.quantity,r.low,r.high];if(values.every(v=>v===''))return;if(values.some(v=>v===''||!Number.isFinite(Number(v))||Number(v)<0)){errors.push(i);return;}const [q,l,h]=values.map(Number);if(h<l||!Number.isFinite(q*h)||!Number.isFinite(q*l)){errors.push(i);return;}low+=q*l;high+=q*h;priced++;});if(!Number.isFinite(low)||!Number.isFinite(high))errors.push(-1);return{low,high,priced,unpriced:rows.length-priced,errors};}
